'use strict';

/**
 * app.js — Hardened Express application
 * Addresses: OWASP A01 (Broken Access Control), A02 (Sensitive Data Exposure),
 *            A03 (Injection), A04 (Insecure Design), A05 (Security Misconfiguration),
 *            A07 (Broken Authentication)
 */

const express = require('express');
const helmet  = require('helmet');           // A05: Security headers
const rateLimit = require('express-rate-limit'); // A04: Rate limiting
const jwt     = require('jsonwebtoken');     // A07: Authentication
const { query, validationResult } = require('express-validator'); // A03: Input validation

const app = express();

// ── 1. SECURITY HEADERS (OWASP A05) ──────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, HSTS, CSP, and more.
app.use(helmet());

// ── 2. BODY PARSING WITH SIZE LIMITS (OWASP A04) ─────────────────────────────
// Prevents large-payload DoS attacks.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ── 3. RATE LIMITING (OWASP A04) ─────────────────────────────────────────────
// 100 requests per IP per 15-minute window across all routes.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,    // Return rate-limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ── 4. AUTHENTICATION MIDDLEWARE (OWASP A01 / A07) ───────────────────────────
// Validates a signed JWT supplied as:  Authorization: Bearer <token>
// JWT_SECRET must be set in the environment — never hardcode it here.
function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized: no token provided.' });
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    // Fail closed: if the secret is misconfigured, deny all requests.
    console.error('FATAL: JWT_SECRET environment variable is not set.');
    return res.status(500).json({ error: 'Internal Server Error' });
  }

  jwt.verify(token, secret, { algorithms: ['HS256'] }, (err, payload) => {
    if (err) {
      return res.status(403).json({ error: 'Forbidden: invalid or expired token.' });
    }
    req.user = payload; // Attach verified identity to request
    next();
  });
}

// ── 5. ROUTES ─────────────────────────────────────────────────────────────────

// Public health check — no auth required, intentionally minimal data.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected user listing (OWASP A01 / A02):
//   - Requires valid JWT (authenticate)
//   - Validates & sanitises the optional ?limit query param (express-validator)
//   - Returns only non-sensitive fields (id, name) — email is omitted
app.get(
  '/users',
  authenticate,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be an integer between 1 and 100')
    .toInt(),
  (req, res) => {
    // Return validation errors before touching any data
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app this data would come from a parameterised DB query,
    // never via string interpolation (guards against SQL/NoSQL injection).
    const users = [
      { id: 1, name: 'Alice' }, // email intentionally excluded (A02)
      { id: 2, name: 'Bob'   },
    ];

    const limit = req.query.limit ?? users.length;
    res.json(users.slice(0, limit));
  }
);

// ── 6. GLOBAL ERROR HANDLER (OWASP A05) ──────────────────────────────────────
// Must be registered AFTER all routes.
// Logs the full error internally but NEVER exposes stack traces to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err.stack);
  res.status(500).json({ error: 'Internal Server Error' });
});

// ── 7. SERVER STARTUP ─────────────────────────────────────────────────────────
// Port sourced from environment; hardcoded fallback for local development only.
const PORT = parseInt(process.env.PORT, 10) || 3000;

/* istanbul ignore next */
if (require.main === module) {
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

