'use strict';

/**
 * app.js — Hardened Express application
 *
 * Security fixes applied (OWASP Top 10 2021):
 *  A01 – Broken Access Control     → requireAuth middleware on sensitive routes
 *  A02 – Cryptographic/Data Exposure → env-driven secrets, minimal response fields
 *  A03 – Injection                 → body-size limits, input validation via express-validator
 *  A04 – Insecure Design / DoS     → rate limiting via express-rate-limit
 *  A05 – Security Misconfiguration → helmet (security headers), no X-Powered-By leak
 */

const express   = require('express');
const helmet    = require('helmet');           // npm install helmet
const rateLimit = require('express-rate-limit'); // npm install express-rate-limit
const jwt       = require('jsonwebtoken');     // npm install jsonwebtoken
const { body, validationResult } = require('express-validator'); // npm install express-validator

const app  = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. Security headers (OWASP A05 – Security Misconfiguration)
//    Disables X-Powered-By, sets CSP, HSTS, X-Frame-Options, etc.
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. Rate limiting (OWASP A04 – Insecure Design / DoS prevention)
//    100 requests per 15-minute window per IP across all routes.
// ---------------------------------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 3. Body parsing with strict size limits (OWASP A03 – Injection / payload bombing)
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 4. Authentication middleware (OWASP A01 – Broken Access Control)
//    Validates a signed JWT in the Authorization: Bearer <token> header.
//    JWT_SECRET MUST be set in the environment — never hard-code it.
// ---------------------------------------------------------------------------
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // "Bearer <token>"

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized: missing token' });
  }

  const secret = process.env.JWT_SECRET;
  if (!secret) {
    // Fail closed: if the secret is not configured, deny all requests.
    console.error('SECURITY: JWT_SECRET environment variable is not set');
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  try {
    const payload = jwt.verify(token, secret);
    req.user = payload;
    next();
  } catch {
    return res.status(403).json({ error: 'Forbidden: invalid or expired token' });
  }
}

// ---------------------------------------------------------------------------
// 5. Mock data store (replace with a parameterised DB query in production)
// ---------------------------------------------------------------------------
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com'   },
];

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

// Public health-check — no auth required, but still rate-limited + helmet-protected.
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected user listing (OWASP A01 + A02)
//  • requireAuth  — only authenticated callers
//  • Minimal response — emails are omitted (return only what the caller needs)
app.get('/users', requireAuth, (req, res) => {
  const safeUsers = users.map(({ id, name }) => ({ id, name })); // strip email
  res.json(safeUsers);
});

// Protected user creation with input validation (OWASP A03 – Injection)
app.post(
  '/users',
  requireAuth,
  // Validate and sanitise every input field before it touches business logic
  body('name')
    .isString()
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape(),
  body('email')
    .isEmail()
    .normalizeEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Safe to use req.body here — it has been validated and sanitised.
    const { name, email } = req.body;
    const newUser = { id: users.length + 1, name, email };
    users.push(newUser);

    // Return only non-sensitive fields
    res.status(201).json({ id: newUser.id, name: newUser.name });
  },
);

// ---------------------------------------------------------------------------
// Start server
// ---------------------------------------------------------------------------
app.listen(PORT, () => {
  // Avoid logging the exact port in production to reduce information leakage.
  if (process.env.NODE_ENV !== 'production') {
    console.log(`Server running on port ${PORT}`);
  } else {
    console.log('Server started');
  }
});

module.exports = app;

