// app.js — hardened version
'use strict';

const express = require('express');
const helmet  = require('helmet');          // Security headers (Finding 4)
const rateLimit = require('express-rate-limit'); // Rate limiting (Finding 5)

const app = express();

// ── Middleware ────────────────────────────────────────────────────────────────

// 1. Parse JSON bodies (with size cap to prevent payload-flooding)
app.use(express.json({ limit: '10kb' }));

// 2. Security headers via helmet (X-Frame-Options, CSP, HSTS, etc.)
app.use(helmet());

// 3. Global rate limiter — 100 requests per 15 min per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ── Auth middleware ───────────────────────────────────────────────────────────

/**
 * requireAuth — verifies a Bearer token from the Authorization header.
 * Replace with a real JWT / session strategy (e.g. passport-jwt) in production.
 */
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header.' });
  }

  const token = authHeader.slice(7); // strip "Bearer "

  // ✅ Compare against an env-sourced secret — never hardcode tokens
  if (token !== process.env.API_TOKEN) {
    return res.status(403).json({ error: 'Forbidden.' });
  }

  next();
}

// ── Input validation helper ───────────────────────────────────────────────────

/**
 * Validate a user-supplied integer ID from req.params.
 * Returns the parsed integer, or null if invalid.
 */
function parseIntParam(value) {
  const n = Number(value);
  return Number.isInteger(n) && n > 0 ? n : null;
}

// ── Routes ────────────────────────────────────────────────────────────────────

// Health check — public, no sensitive data
app.get('/health', (req, res) => {
  // ✅ Do NOT expose internal details (versions, env, uptime) here
  res.json({ status: 'ok' });
});

// List users — protected; returns only non-sensitive fields
app.get('/users', requireAuth, (req, res) => {
  // ✅ In production, query your DB here.
  // ✅ Never return password hashes, SSNs, raw emails unless the caller needs them.
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob'   },
  ];
  res.json(users);
});

// Get single user — protected + input validation
app.get('/users/:id', requireAuth, (req, res) => {
  const id = parseIntParam(req.params.id); // ✅ Validate before use
  if (id === null) {
    return res.status(400).json({ error: 'Invalid user ID.' });
  }

  // ✅ In production: use a parameterised query, e.g.:
  //   db.query('SELECT id, name FROM users WHERE id = $1', [id])
  const users = { 1: { id: 1, name: 'Alice' }, 2: { id: 2, name: 'Bob' } };
  const user  = users[id];

  if (!user) {
    return res.status(404).json({ error: 'User not found.' });
  }
  res.json(user);
});

// ── Error handler ─────────────────────────────────────────────────────────────

// ✅ Catch-all: never leak stack traces or internal errors to the client
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  console.error(err); // log server-side only
  res.status(500).json({ error: 'Internal server error.' });
});

// ── Start ─────────────────────────────────────────────────────────────────────

const PORT = Number(process.env.PORT) || 3000;
app.listen(PORT, () => {
  // ✅ Never log secrets or full config at startup
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

