'use strict';

/**
 * app.js — Hardened Express Application
 *
 * Security fixes applied (OWASP Top 10):
 *  - [A01] Broken Access Control      → JWT authentication middleware on protected routes
 *  - [A02] Sensitive Data Exposure     → PII removed from source; response fields filtered
 *  - [A03] Injection                   → express-validator input validation scaffolded
 *  - [A05] Security Misconfiguration   → helmet headers, CORS policy, body size limits,
 *                                        env-driven config
 *  - [A07] Auth Failures               → rate limiting on all routes
 */

const express = require('express');
const helmet  = require('helmet');
const cors    = require('cors');
const rateLimit = require('express-rate-limit');
const jwt     = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');

const app  = express();
const PORT = process.env.PORT || 3000;

// ---------------------------------------------------------------------------
// 1. SECURITY HEADERS (OWASP A05)
//    helmet sets X-Frame-Options, X-Content-Type-Options, HSTS, CSP, etc.
// ---------------------------------------------------------------------------
app.use(helmet());

// ---------------------------------------------------------------------------
// 2. CORS POLICY (OWASP A05)
//    Restrict cross-origin requests to known, trusted origins only.
//    Set ALLOWED_ORIGIN in your environment; never use '*' in production.
// ---------------------------------------------------------------------------
app.use(cors({
  origin: process.env.ALLOWED_ORIGIN || 'https://yourdomain.com',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));

// ---------------------------------------------------------------------------
// 3. BODY PARSING WITH SIZE LIMITS (OWASP A05)
//    Explicit size cap prevents denial-of-service via oversized payloads.
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 4. GLOBAL RATE LIMITING (OWASP A07)
//    100 requests per IP per 15-minute window.  Tighten on auth routes.
// ---------------------------------------------------------------------------
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
