  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /users
 * Protected endpoint (OWASP A01, A02):
 *  - Requires a valid JWT.
 *  - Returns only non-sensitive fields (id, name). Email is omitted.
 *
 * NOTE: Replace the static array with a parameterised database query.
 *       Never store real PII in source code.
 */
