  //   const users = await db.query('SELECT id, name FROM users WHERE active = $1', [true]);
  const users = [
    { id: 1, name: 'Alice' }, // email intentionally omitted from response
    { id: 2, name: 'Bob'   },
  ];

  res.json(users);
});

/**
 * POST /users
 * Demonstrates input validation (OWASP A03 — Injection prevention).
 * All fields are validated and sanitised before use.
 */
app.post(
  '/users',
  authenticateToken,
  [
    body('name')
      .isString()
      .trim()
      .escape()                     // HTML-encode special chars to prevent XSS
      .isLength({ min: 1, max: 100 })
      .withMessage('name must be between 1 and 100 characters.'),

    body('email')
      .isEmail()
      .normalizeEmail()             // Canonicalise the address
      .withMessage('A valid email address is required.'),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Return structured 400 so clients can surface field-level messages
      return res.status(400).json({ errors: errors.array() });
    }

    const { name, email } = req.body; // safe to use after validation
    // TODO: insert into database with a parameterised query to prevent SQL injection:
    //   await db.query('INSERT INTO users (name, email) VALUES ($1, $2)', [name, email]);
    res.status(201).json({ message: 'User created.', user: { name } }); // never echo email back
  }
);

// ---------------------------------------------------------------------------
// GLOBAL ERROR HANDLER
// Prevents stack traces and internal details leaking to clients (OWASP A05).
// ---------------------------------------------------------------------------
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(err); // Log full error server-side only
  res.status(500).json({ error: 'An unexpected error occurred.' });
});

// ---------------------------------------------------------------------------
// START SERVER
// ---------------------------------------------------------------------------
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

