'use strict';

const express = require('express');
const helmet = require('helmet');           // FIX #4 & #5: Security headers + removes X-Powered-By
const rateLimit = require('express-rate-limit'); // FIX #6: Rate limiting
const cors = require('cors');              // FIX #7: Explicit CORS policy

const app = express();

// ─── FIX #5: Remove framework fingerprinting header ───────────────────────────
app.disable('x-powered-by');

// ─── FIX #4: Apply secure HTTP headers via helmet ────────────────────────────
app.use(helmet());

// ─── FIX #7: Explicit, restrictive CORS policy ───────────────────────────────
const ALLOWED_ORIGINS = (process.env.ALLOWED_ORIGINS || '')
  .split(',')
  .map((o) => o.trim())
  .filter(Boolean);

app.use(
  cors({
    origin: (origin, callback) => {
      // Allow requests with no origin (e.g. server-to-server) only in dev
      if (!origin && process.env.NODE_ENV !== 'production') return callback(null, true);
      if (ALLOWED_ORIGINS.includes(origin)) return callback(null, true);
      callback(new Error(`CORS policy: origin '${origin}' not allowed`));
    },
    methods: ['GET'],          // Restrict to methods this app actually uses
    allowedHeaders: ['Authorization', 'Content-Type'],
    credentials: true,
  })
);

// ─── FIX #8: Limit request body size to prevent payload-based DoS ────────────
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── FIX #6: Global rate limiter — max 100 requests per 15 min per IP ────────
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,   // Return RateLimit-* headers (RFC 6585)
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// Tighter limiter for sensitive data endpoints
const dataLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: { error: 'Too many requests to this endpoint.' },
});

// ─── FIX #3: Simple bearer-token authentication middleware ────────────────────
// Replace this stub with your real JWT/session verification logic.
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authentication required.' });
  }
  const token = authHeader.slice(7);
  // TODO: verify token with your JWT library / session store, e.g.:
  //   const payload = jwt.verify(token, process.env.JWT_SECRET);
  //   req.user = payload;
  if (!token || token.length < 20) {
    return res.status(401).json({ error: 'Invalid or expired token.' });
  }
  next();
}

// ─── FIX #3 (input validation): Query-parameter sanitisation helper ───────────
// Extend this using a library like `zod` or `joi` for complex schemas.
function validatePaginationQuery(req, res, next) {
  const { page, limit } = req.query;
  if (page !== undefined && !/^\d+$/.test(page)) {
    return res.status(400).json({ error: "Query param 'page' must be a positive integer." });
  }
  if (limit !== undefined && !/^\d+$/.test(limit)) {
    return res.status(400).json({ error: "Query param 'limit' must be a positive integer." });
  }
  next();
}

// ─── Routes ───────────────────────────────────────────────────────────────────

// Health check — public, but still rate-limited globally
app.get('/health', (req, res) => {
  // FIX: do not expose internal timestamps or version info to unauthenticated callers
  res.json({ status: 'ok' });
});

// FIX #1 & #2: /users now requires authentication, has a tighter rate limit,
// validates query params, and masks PII in the response.
app.get(
  '/users',
  requireAuth,
  dataLimiter,
  validatePaginationQuery,
  (req, res) => {
    // FIX #2: Never return raw PII fields (e.g. email) to the client.
    // Only expose the minimum necessary fields for the caller's role.
    // In a real app, fetch from DB and apply field-level authorisation.
    const users = [
      { id: 1, name: 'Alice' },   // email intentionally omitted
      { id: 2, name: 'Bob' },
    ];
    res.json(users);
  }
);

// ─── FIX #9 & #10: Centralised error handler ─────────────────────────────────
// Catches all errors passed via next(err); never leaks stack traces to clients.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the full error server-side (replace with your structured logger, e.g. pino/winston)
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    error: err.message,
    // stack only logged in non-production environments
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });

  // CORS errors
  if (err.message && err.message.startsWith('CORS policy')) {
    return res.status(403).json({ error: err.message });
  }

  // Generic safe response — never expose internal details to the client
  res.status(err.status || 500).json({ error: 'An unexpected error occurred.' });
});

// ─── Server startup ───────────────────────────────────────────────────────────
if (require.main === module) {
  const PORT = parseInt(process.env.PORT || '3000', 10);
  app.listen(PORT, '127.0.0.1', () => {             // FIX: bind to localhost, not 0.0.0.0
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

