// FIX (OWASP A09): Log every request for monitoring and incident response.
// Use 'combined' in production for full Apache-style logs.
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ─── 4. GLOBAL RATE LIMITER ─────────────────────────────────────────────────
// FIX (OWASP A04): Limit each IP to 100 requests per 15-minute window.
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,    // Return limit info in RateLimit-* headers
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ─── 5. AUTHENTICATION MIDDLEWARE ───────────────────────────────────────────
// FIX (OWASP A07): Protect routes behind token verification.
// Replace this stub with a real JWT/session check (e.g. jsonwebtoken.verify).
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Authentication required.' });
  }

  // TODO: Replace with real verification, e.g.:
  // jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
  //   if (err) return res.status(403).json({ error: 'Invalid token.' });
  //   req.user = user;
  //   next();
  // });

  // Stub: accept any non-empty token for now (REMOVE IN PRODUCTION)
  req.user = { id: token }; // placeholder
  next();
}

// ─── 6. ROUTES ──────────────────────────────────────────────────────────────

// Health check — public, but reveals no sensitive internals
app.get('/health', (req, res) => {
  // FIX (OWASP A02): Don't leak server timestamps or version info in production
  const payload = { status: 'ok' };
