/**
 * app.js — Hardened Express Application
 * Security fixes applied for OWASP Top 10:
 *   - Sensitive data exposure     → auth middleware + field filtering + pagination
 *   - Injection                   → parameterized queries + strict input parsing
 *   - Missing input validation    → zod schema validation on all input
 *   - Security misconfiguration   → helmet headers + x-powered-by removed
 *   - Broken authentication       → token auth middleware on protected routes
 *   - DoS / brute-force           → rate limiting via express-rate-limit
 */

'use strict';

const express   = require('express');
const helmet    = require('helmet');        // npm install helmet
const rateLimit = require('express-rate-limit'); // npm install express-rate-limit
const { z }     = require('zod');           // npm install zod

const app = express();

// ── Security headers (helmet sets CSP, HSTS, X-Frame-Options, etc.) ──────────
app.use(helmet());
app.disable('x-powered-by'); // remove Express fingerprint header

// ── Body parsing — limit payload size to prevent large-payload DoS ────────────
app.use(express.json({ limit: '10kb' }));

// ── Global rate limiter — 100 requests per IP per 15-minute window ────────────
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ── Auth middleware ───────────────────────────────────────────────────────────
// Replace `isValidToken` with real JWT verification (e.g. jsonwebtoken.verify)
// in production. Never hardcode secrets — read from process.env.
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'] ?? '';
  const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7) : null;

  if (!token || !isValidToken(token)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

function isValidToken(token) {
  // TODO: replace with → jwt.verify(token, process.env.JWT_SECRET)
  return typeof token === 'string' && token.length > 0;
}

// ── Input validation schemas (zod) ───────────────────────────────────────────
const PaginationSchema = z.object({
  page:  z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

const UserIdSchema = z.object({
  id: z.coerce.number().int().positive(),
});

const CreateUserSchema = z.object({
  name:  z.string().min(1).max(100).trim(),
  email: z.string().email().max(254).toLowerCase(),
});

// ── Routes ────────────────────────────────────────────────────────────────────

// GET /health — minimal response, no PII or server detail
app.get('/health', (_req, res) => {
  res.json({ status: 'ok' });
});

// GET /users — protected, paginated, email field omitted
app.get('/users', requireAuth, (req, res) => {
  const parsed = PaginationSchema.safeParse(req.query);
  if (!parsed.success) {
    return res.status(400).json({ error: parsed.error.flatten() });
  }
  const { page, limit } = parsed.data;

  // Replace with a real parameterized DB query, e.g.:
  //   SELECT id, name FROM users ORDER BY id LIMIT $1 OFFSET $2
  const allUsers = getUsers();
  const start     = (page - 1) * limit;
  const safeUsers = allUsers
    .slice(start, start + limit)
    .map(({ id, name }) => ({ id, name }));  // ← email intentionally omitted

  res.json({ data: safeUsers, page, limit, total: allUsers.length });
});

// GET /users/:id — protected, validates ID before any DB lookup
app.get('/users/:id', requireAuth, (req, res) => {
  const parsed = UserIdSchema.safeParse({ id: req.params.id });
  if (!parsed.success) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  // Replace with a parameterized query, e.g.:
  //   db.query('SELECT id, name FROM users WHERE id = $1', [parsed.data.id])
  const user = getUsers().find(u => u.id === parsed.data.id);
  if (!user) return res.status(404).json({ error: 'User not found' });

  const { id, name } = user; // strip email before responding
  res.json({ id, name });
});

// POST /users — protected, full schema validation before processing
app.post('/users', requireAuth, (req, res) => {
  const parsed = CreateUserSchema.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ error: parsed.error.flatten() });
  }

  const { name, email } = parsed.data;

  // Replace with a parameterized INSERT, e.g.:
  //   db.query('INSERT INTO users (name, email) VALUES ($1, $2)', [name, email])
  const newUser = createUser({ name, email });

  res.status(201).json({ id: newUser.id, name: newUser.name });
});

// ── Stub data helpers (replace with real DB calls) ────────────────────────────
function getUsers() {
  return [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];
}

function createUser({ name, email }) {
  return { id: Date.now(), name, email }; // stub — use DB insert in production
}

// ── Start server ──────────────────────────────────────────────────────────────
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

