/**
 * app.js — Security-hardened Express application
 *
 * Fixes applied:
 *  1. Helmet for security headers (XSS, clickjacking, MIME sniffing, HSTS)
 *  2. Rate limiting (DoS / brute-force protection)
 *  3. Body parser with size cap (DoS protection)
 *  4. JWT authentication middleware on protected routes
 *  5. Input validation via express-validator
 *  6. No hardcoded PII — data layer abstracted behind a db module
 *  7. Minimal /health endpoint (no information leakage)
 *  8. Generic error messages (no internal detail leakage)
 */

'use strict';

const express    = require('express');
const helmet     = require('helmet');           // npm i helmet
const rateLimit  = require('express-rate-limit'); // npm i express-rate-limit
const jwt        = require('jsonwebtoken');      // npm i jsonwebtoken
const { body, validationResult } = require('express-validator'); // npm i express-validator

const app = express();

// ─── 1. Security Headers ────────────────────────────────────────────────────
// Sets X-Frame-Options, X-Content-Type-Options, Strict-Transport-Security,
// Content-Security-Policy, and more.
app.use(helmet());

// ─── 2. Rate Limiting ────────────────────────────────────────────────────────
// 100 requests per 15 minutes per IP (tighten on auth routes).
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(globalLimiter);

// ─── 3. Body Parsing with Size Cap ──────────────────────────────────────────
// Prevents oversized payload attacks.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── 4. Authentication Middleware ────────────────────────────────────────────
// Verifies a signed JWT in the Authorization: Bearer <token> header.
// JWT_SECRET must be set in environment (never hardcode it).
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Forbidden' });
  }
}

// ─── 5. Routes ───────────────────────────────────────────────────────────────

// Health check — minimal response, no server internals exposed.
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// List users — authenticated, no PII returned beyond what is necessary.
// Replace `db` with your actual database client/ORM.
app.get('/users', requireAuth, async (req, res) => {
  try {
    // Example: SELECT only non-sensitive columns; never SELECT *
    const users = await db.query('SELECT id, name FROM users');
    res.json(users.rows);
  } catch {
    // Never forward raw error messages to the client.
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Create user — authenticated + validated input.
app.post('/users', requireAuth, [
  body('name')
    .isString()
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape(),
  body('email')
    .isEmail()
    .normalizeEmail(),
], async (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  try {
    const { name, email } = req.body;
    const newUser = await db.query(
      'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING id, name',
      [name, email] // parameterized — prevents SQL injection
    );
    res.status(201).json(newUser.rows[0]);
  } catch {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ─── 6. Start Server ─────────────────────────────────────────────────────────
const PORT = parseInt(process.env.PORT, 10) || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

