'use strict';

/**
 * app.js — Hardened Express application
 * Security fixes applied per OWASP Top 10 review.
 * Required packages: express, helmet, express-rate-limit, express-validator, jsonwebtoken
 * Install: npm install express helmet express-rate-limit express-validator jsonwebtoken
 */

const express    = require('express');
const helmet     = require('helmet');
const rateLimit  = require('express-rate-limit');
const jwt        = require('jsonwebtoken');
const { param, validationResult } = require('express-validator');

const app = express();

// ─── 1. SECURITY HEADERS (OWASP A05) ─────────────────────────────────────────
// Sets X-Frame-Options, Content-Security-Policy, X-Content-Type-Options, etc.
// Also removes the X-Powered-By header automatically.
app.use(helmet());

// ─── 2. BODY PARSING — capped to prevent large-payload DoS (OWASP A04) ───────
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ─── 3. RATE LIMITING (OWASP A04 – Insecure Design) ─────────────────────────
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15-minute window
  max: 100,                  // max 100 requests per IP per window
  standardHeaders: true,     // return rate-limit info in RateLimit-* headers
  legacyHeaders: false,      // disable X-RateLimit-* headers
  message: { error: 'Too many requests. Please try again later.' },
});
app.use(limiter);

// ─── 4. AUTHENTICATION MIDDLEWARE (OWASP A01 – Broken Access Control) ────────
// Verifies a signed JWT passed as:  Authorization: Bearer <token>
function authenticate(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized: missing token.' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    return res.status(403).json({ error: 'Forbidden: invalid or expired token.' });
  }
}

// ─── IN-MEMORY DATA (replace with a parameterised DB query in production) ─────
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com', passwordHash: '***' },
  { id: 2, name: 'Bob',   email: 'bob@example.com',   passwordHash: '***' },
];

// ─── ROUTES ───────────────────────────────────────────────────────────────────

// Public health-check — no sensitive data returned
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected: list users
// FIX (OWASP A01): requires valid JWT
// FIX (OWASP A02): strips sensitive fields (passwordHash, email) before responding
app.get('/users', authenticate, (req, res) => {
  const safeUsers = users.map(({ id, name }) => ({ id, name }));
  res.json(safeUsers);
});

// Protected: get user by ID
// FIX (OWASP A03): input is validated and coerced — never used raw
app.get(
  '/users/:id',
  authenticate,
  param('id').isInt({ min: 1 }).toInt(), // validate & sanitize
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const user = users.find(u => u.id === req.params.id);
    if (!user) return res.status(404).json({ error: 'User not found.' });

    // Return only safe fields
    const { id, name } = user;
    res.json({ id, name });
  }
);

// ─── 5. CENTRALISED ERROR HANDLER (OWASP A09 – Logging & Monitoring) ─────────
// Must be registered AFTER all routes.
// Logs full details internally; never leaks stack traces to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Unhandled error on ${req.method} ${req.path}:`, err);
  res.status(err.status || 500).json({ error: 'Internal Server Error' });
});

// ─── SERVER ───────────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

