]);
```

**Fix:** Return only the minimum necessary fields, and never expose raw PII without authorization:
```js
// ✅ AFTER — Strip sensitive fields; only expose what's needed
app.get('/users', authenticate, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // Only return email if the requester has admin scope
  const safeUsers = users.map(({ id, name, email }) => ({
    id,
    name,
    ...(req.user.role === 'admin' ? { email } : {}),
  }));

  res.json(safeUsers);
});
```

---

#### 🟠 3. No Rate Limiting — Brute-force & DoS risk
**Problem:** There are no rate limits on any endpoint. Attackers can flood the server with requests, enabling brute-force attacks or denial of service.

**Fix:** Use `express-rate-limit`:
```js
// ✅ AFTER — Apply rate limiting globally
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});

app.use(limiter);
```

---

#### 🟠 4. Missing HTTP Security Headers
**Problem:** Without security headers, the app is vulnerable to clickjacking, MIME sniffing, XSS, and information disclosure (e.g., `X-Powered-By: Express` leaks tech stack).

**Fix:** Use the `helmet` middleware to set secure headers in one line:
```js
// ✅ AFTER — Harden HTTP headers with helmet
const helmet = require('helmet');
app.use(helmet());
// Sets: Content-Security-Policy, X-Frame-Options, X-Content-Type-Options,
//       Strict-Transport-Security, removes X-Powered-By, and more
```

---

#### 🟠 5. No Input Validation — Injection risk
**Problem:** The app has no `express.json()` body parser and no input validation. Future routes that accept query params or request bodies will be vulnerable to injection (NoSQL, SQL, command) and malformed-input crashes.

**Fix:** Add body parsing with a size limit and use a validation library:
```js
// ✅ AFTER — Parse and validate all input
const { body, query, validationResult } = require('express-validator');

// Global body parser with size cap (see also #6)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Example: validated POST route
app.post('/users',
  authenticate,
  body('name').isString().trim().notEmpty().isLength({ max: 100 }),
  body('email').isEmail().normalizeEmail(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // safe to use req.body here
  }
);
```

---

#### 🟡 6. No Request Body Size Limit — DoS via large payloads
**Problem:** Without a body size limit, an attacker can send a multi-GB payload to exhaust memory. (Partially addressed above in fix #5 with `limit: '10kb'`.)

```js
// ✅ Already covered in fix #5 — but shown explicitly:
app.use(express.json({ limit: '10kb' }));
```

---

#### 🟡 7. No Centralized Error Handling or Security Logging
**Problem:** Unhandled errors will expose stack traces to clients. There is also no logging of auth failures or suspicious activity.

**Fix:** Add a global error handler and structured logging:
```js
// ✅ AFTER — Catch-all error handler (add at the END of all routes)
app.use((err, req, res, next) => {
  console.error({ // Replace with structured logger (winston/pino) in production
    timestamp: new Date().toISOString(),
    path: req.path,
    error: err.message,
    // Never log err.stack to the client response
  });

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'  // ✅ Safe: hides internals
      : err.message              // Dev-only detail
  });
});
```

---

#### 🟢 8. Hardcoded Port — No environment configuration
**Problem:** Port `3000` is hardcoded. This makes it impossible to reconfigure without code changes and is a bad-practice signal for other potential hardcoded secrets.

```js
// ❌ BEFORE
app.listen(3000, () => { ... });
```
```js
// ✅ AFTER — Use environment variables
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

---

### ✅ Fully Patched `app.js`

```js
'use strict';

require('dotenv').config();
const express    = require('express');
const helmet     = require('helmet');
const rateLimit  = require('express-rate-limit');
const jwt        = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');

const app = express();

// ── Security middleware ──────────────────────────────────────────────────────
app.use(helmet());                                    // Secure HTTP headers
app.use(express.json({ limit: '10kb' }));             // Body parsing + size cap
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ── Auth middleware ──────────────────────────────────────────────────────────
function authenticate(req, res, next) {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Missing token' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid or expired token' });
    req.user = user;
    next();
  });
}

// ── Routes ───────────────────────────────────────────────────────────────────
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticate, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  const safeUsers = users.map(({ id, name, email }) => ({
    id,
    name,
    ...(req.user.role === 'admin' ? { email } : {}),
  }));

  res.json(safeUsers);
});

// ── Global error handler (must be last) ──────────────────────────────────────
app.use((err, req, res, next) => {
  console.error({
    timestamp: new Date().toISOString(),
    path: req.path,
    error: err.message,
  });

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message,
  });
});

// ── Start ────────────────────────────────────────────────────────────────────
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

---

### 📦 Required Packages

```bash
npm install helmet express-rate-limit jsonwebtoken express-validator dotenv
```

And your `.env` file:
```
JWT_SECRET=your-long-random-secret-here   # Use: openssl rand -hex 64
NODE_ENV=production
PORT=3000
```

---

### Priority Order for Remediation

1. 🔴 **Add authentication** immediately — data is publicly exposed right now
2. 🔴 **Restrict sensitive data** in API responses
3. 🟠 **Add `helmet`** — single line, zero cost, high impact
4. 🟠 **Add rate limiting** — protects against brute force and DoS
5. 🟠 **Add input validation** — critical before any write endpoints are added
6. 🟡 **Add error handling + logging** — before going to production

