 * app.js — Hardened Express application
 *
 * Security fixes applied (OWASP Top 10):
 *  - [A01] Broken Access Control      → requireAuth middleware on /users
 *  - [A02] Sensitive Data Exposure    → PII (email) stripped from responses
 *  - [A03] Injection                  → express-validator on all user input
 *  - [A05] Security Misconfiguration  → helmet headers, body-size limits,
 *                                       server timestamp removed, env-based port
 *  - [A07] Auth Failures              → rate limiting on all routes
 */

'use strict';

const express = require('express');
const helmet = require('helmet');           // npm install helmet
const rateLimit = require('express-rate-limit'); // npm install express-rate-limit
const { query, validationResult } = require('express-validator'); // npm install express-validator

const app = express();

// ─── 1. Security Headers (OWASP A05) ─────────────────────────────────────────
// Sets X-Content-Type-Options, X-Frame-Options, HSTS, CSP, and 10+ others.
// Removes the X-Powered-By: Express fingerprint automatically.
app.use(helmet());

// ─── 2. Rate Limiting (OWASP A07) ────────────────────────────────────────────
// Limits each IP to 100 requests per 15-minute window across all routes.
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  standardHeaders: true,  // Return rate limit info in RateLimit-* headers
  legacyHeaders: false,   // Disable X-RateLimit-* headers
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ─── 3. Body Parsing with Size Limits (OWASP A05) ────────────────────────────
// Explicit 10 KB cap prevents memory-exhaustion DoS via oversized payloads.
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ─── 4. Authentication Middleware (OWASP A01 / A07) ──────────────────────────
// Replace `isValidToken` with your real JWT verification or session lookup.
function isValidToken(token) {
  // TODO: verify token signature and expiry against your auth provider
  // e.g. return jwt.verify(token, process.env.JWT_SECRET);
  return typeof token === 'string' && token.length > 0;
}

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'] ?? '';
  const token = authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  if (!token || !isValidToken(token)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
}

// ─── Routes ───────────────────────────────────────────────────────────────────

/**
 * GET /health
 * Public liveness probe — intentionally returns no implementation details.
 */
app.get('/health', (req, res) => {
  // FIXED: timestamp removed to prevent server-clock leakage (OWASP A05)
  res.json({ status: 'ok' });
});

/**
 * GET /users
 * Protected: requires a valid Bearer token.
 * Accepts an optional ?role= query parameter (alpha chars only).
 *
 * FIXED (A01): requireAuth gate added.
 * FIXED (A02): email (PII) excluded from response.
 * FIXED (A03): query param validated + sanitised via express-validator.
 */
app.get(
  '/users',
  requireAuth,
  // Input validation — whitelist alphanumeric role values, strip any HTML
  query('role')
    .optional()
    .isAlpha().withMessage('role must contain letters only')
    .trim()
    .escape(),
  (req, res) => {
    // Reject the request immediately if validation failed
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Return only non-sensitive fields — never include email, password hash, etc.
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];

    // Optional: filter by role if your data model supports it
    // const { role } = req.query;
    // const filtered = role ? users.filter(u => u.role === role) : users;

    res.json(users);
  }
);

// ─── 5. Global Error Handler ──────────────────────────────────────────────────
// Catches any unhandled errors and returns a safe, generic message.
// Never surface stack traces or internal details to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  console.error(err); // Log internally for observability
  res.status(500).json({ error: 'Internal server error' });
});

// ─── 6. Environment-Based Port (OWASP A05) ───────────────────────────────────
// Hard-coding ports leaks environment assumptions and is a precursor to
// hard-coded secrets. Always read from the environment with a safe fallback.
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

