/**
 * app.js – Hardened Express application
 *
 * Security fixes applied (OWASP Top 10):
 *  [A01] Broken Access Control  – JWT auth middleware on protected routes
 *  [A02] Cryptographic Failures  – HTTPS redirect + HSTS via Helmet
 *  [A03] Injection               – Input validation via Joi; body-size limit
 *  [A04] Insecure Design         – PII stripped from default user response
 *  [A05] Security Misconfiguration – Helmet security headers; hide X-Powered-By
 *  [A07] Auth Failures           – JWT verification required for /users
 *  [A09] Logging & Monitoring    – Morgan access log + global error handler
 *  General                       – Rate limiting; env-based config
 *
 * Required packages (add to package.json):
 *   npm install express helmet morgan express-rate-limit jsonwebtoken joi dotenv
 */

'use strict';

// ---------------------------------------------------------------------------
// 0. Environment configuration – never hard-code secrets or ports
// ---------------------------------------------------------------------------
require('dotenv').config();                        // load .env in development

const PORT       = parseInt(process.env.PORT, 10) || 3000;
const JWT_SECRET = process.env.JWT_SECRET;        // MUST be set in production

if (!JWT_SECRET) {
  console.error('[FATAL] JWT_SECRET environment variable is not set. Exiting.');
  process.exit(1);
}

// ---------------------------------------------------------------------------
// 1. Dependencies
// ---------------------------------------------------------------------------
const express      = require('express');
const helmet       = require('helmet');            // FIX [A05] security headers
const morgan       = require('morgan');            // FIX [A09] access logging
const rateLimit    = require('express-rate-limit');// FIX – rate limiting / DoS
const jwt          = require('jsonwebtoken');      // FIX [A07] authentication
const Joi          = require('joi');               // FIX [A03] input validation

const app = express();

// ---------------------------------------------------------------------------
// 2. Security headers (must come FIRST, before any routes)
//    Fixes: A05 – sets CSP, HSTS, X-Frame-Options, X-Content-Type-Options, etc.
//           Also removes the "X-Powered-By: Express" information-disclosure header.
// ---------------------------------------------------------------------------
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc:  ["'self'"],
      objectSrc:  ["'none'"],
      upgradeInsecureRequests: [],   // FIX [A02] enforce HTTPS in browsers
    },
  },
  hsts: {
    maxAge:            63_072_000,  // 2 years in seconds
    includeSubDomains: true,
    preload:           true,
  },
}));

// ---------------------------------------------------------------------------
// 3. HTTP request logging  –  Fixes [A09]
//    In production, pipe logs to a SIEM / log aggregator instead of stdout.
// ---------------------------------------------------------------------------
app.use(morgan('combined'));

// ---------------------------------------------------------------------------
// 4. Body parser with a strict size limit  –  Fixes [A03] (oversized-body DoS)
// ---------------------------------------------------------------------------
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ---------------------------------------------------------------------------
// 5. Global rate limiter  –  prevents brute-force and DoS
// ---------------------------------------------------------------------------
const globalLimiter = rateLimit({
  windowMs:        15 * 60 * 1000, // 15-minute window
  max:             100,            // max requests per IP per window
  standardHeaders: true,
  legacyHeaders:   false,
  message:         { error: 'Too many requests. Please try again later.' },
});
app.use(globalLimiter);

// Stricter limiter for sensitive / auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max:      20,
  message:  { error: 'Too many auth attempts. Please try again later.' },
});

// ---------------------------------------------------------------------------
// 6. Authentication middleware  –  Fixes [A01, A07]
//    Verifies a Bearer JWT on every protected route.
// ---------------------------------------------------------------------------
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header.' });
  }

  const token = authHeader.slice(7); // strip "Bearer "

  try {
    // jwt.verify throws on invalid / expired tokens
    const payload = jwt.verify(token, JWT_SECRET, {
      algorithms: ['HS256'],       // explicitly whitelist algorithm – prevent "alg: none" attack
    });
    req.user = payload;            // attach verified claims to request
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token.' });
  }
}

// ---------------------------------------------------------------------------
// 7. Input validation helper  –  Fixes [A03]
//    Returns 400 with a structured error if the schema is not satisfied.
// ---------------------------------------------------------------------------
function validate(schema) {
  return (req, res, next) => {
    const { error } = schema.validate(req.query, { abortEarly: false, allowUnknown: false });
    if (error) {
      const messages = error.details.map(d => d.message);
      return res.status(400).json({ error: 'Invalid input.', details: messages });
    }
    next();
  };
}

// Joi schema for /users query parameters
const usersQuerySchema = Joi.object({
