/**
 * app.secure.js — hardened version of app.js
 * Addresses all OWASP findings documented in the security review.
 */

'use strict';

const express  = require('express');
const helmet   = require('helmet');          // FIX #4 – security headers
const rateLimit = require('express-rate-limit'); // FIX #5 – rate limiting
const app      = express();

// ── FIX #1  Missing body parser / input validation baseline ──────────────────
// Enforce a strict JSON body size to prevent DoS via oversized payloads.
app.use(express.json({ limit: '10kb' }));

// ── FIX #4  Missing security headers ─────────────────────────────────────────
// helmet sets X-Content-Type-Options, X-Frame-Options, HSTS, CSP, etc.
app.use(helmet());

// ── FIX #5  No rate limiting ──────────────────────────────────────────────────
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ── FIX #2  Sensitive data exposure — health endpoint ────────────────────────
// BEFORE: leaked server timestamp that aids fingerprinting.
// AFTER:  minimal response; no implementation details.
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// ── FIX #3  Broken authentication + sensitive data exposure — /users ─────────
// BEFORE: unauthenticated endpoint returning PII (email addresses) to anyone.
// AFTER:
//   • requireAuth middleware validates a Bearer token before responding.
//   • Response omits email (or any other PII) unless the caller is authorised
//     to receive it.  Add field-level authorisation as your data model grows.

/**
 * Minimal Bearer-token authentication middleware.
 * Replace the token store with a proper JWT / session implementation.
 */
function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'] || '';
  const token = authHeader.startsWith('Bearer ')
    ? authHeader.slice(7)
    : null;

  if (!token) {
    return res.status(401).json({ error: 'Authentication required.' });
  }

  // TODO: replace with real JWT verification, e.g. jsonwebtoken.verify()
  const VALID_TOKENS = new Set([process.env.API_TOKEN].filter(Boolean));
  if (!VALID_TOKENS.has(token)) {
    return res.status(403).json({ error: 'Forbidden.' });
  }

  next();
}

// ── FIX #6  No input validation on query parameters ──────────────────────────
// If /users ever accepts query params (e.g. ?id=1), validate them strictly.
// Using a simple manual check here; swap in zod / joi for larger schemas.
function validateUsersQuery(req, res, next) {
  const { id } = req.query;
  if (id !== undefined) {
    const parsed = Number(id);
    if (!Number.isInteger(parsed) || parsed < 1) {
      return res.status(400).json({ error: 'id must be a positive integer.' });
    }
    req.query.id = parsed; // normalised, safe value
  }
  next();
}

app.get('/users', requireAuth, validateUsersQuery, (req, res) => {
  // Static data shown for parity with original; in production this would be
  // a parameterised DB query — never string-interpolated SQL (FIX #7).
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];

  // ── FIX #3b  Sensitive data minimisation ─────────────────────────────────
  // Strip PII fields before sending to the client.
  // Only return email if a higher-privilege scope is granted (extend as needed).
  const safeUsers = users.map(({ id, name }) => ({ id, name }));

  if (req.query.id) {
    const user = safeUsers.find(u => u.id === req.query.id);
    return user
      ? res.json(user)
      : res.status(404).json({ error: 'User not found.' });
  }

  res.json(safeUsers);
});

// ── FIX #8  Global error handler ─────────────────────────────────────────────
// Prevents stack traces / internal details leaking to the client.
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, _next) => {
  console.error(err); // log internally
  res.status(500).json({ error: 'An unexpected error occurred.' });
});

// ── FIX #9  Hard-coded port ───────────────────────────────────────────────────
// Read from environment so the port is not baked into source code.
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

