## ✅ Consolidated Fixed `app.js`

```js
'use strict';

const express   = require('express');
const helmet    = require('helmet');
const rateLimit = require('express-rate-limit');
const jwt       = require('jsonwebtoken');

const app = express();

// ── Security middleware ────────────────────────────────────────────────────
app.use(helmet());
app.use(express.json({ limit: '10kb' })); // prevent payload flooding
app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100, standardHeaders: true }));

// ── Auth middleware ────────────────────────────────────────────────────────
const requireAuth = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch {
    res.status(403).json({ error: 'Forbidden' });
  }
};

// ── Routes ─────────────────────────────────────────────────────────────────
app.get('/health', (_req, res) => {
  res.json({ status: 'ok' }); // no timestamp leak
});

app.get('/users/me', requireAuth, async (req, res) => {
  try {
    // Use parameterized query — never interpolate req.user.id into SQL
    const user = await db.query(
      'SELECT id, name FROM users WHERE id = $1',
      [req.user.id]
    );
    if (!user.rows.length) return res.status(404).json({ error: 'Not found' });
    res.json(user.rows[0]);
  } catch {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ── Start ──────────────────────────────────────────────────────────────────
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
}

module.exports = app;
```

